open_ids = db_list_tickets('open')
selected = []
for tid in open_ids:
    t = db_get_ticket(tid)
    if t['age_days'] > 21:
        selected.append(tid)
for tid in selected:
    db_update_ticket(tid, 'closed')
print(len(selected))

files = ['codec.py','import.py','config.py','billing.py','export.py','client.py','cache.py','metrics.py']
info = {}
for f in files:
    info[f] = git_last_commit(f)
selected = []
for f in files:
    if info[f]['author'] == 'Noah Petrov':
        tag = 'review-' + f[:-3]
        selected.append((tag, info[f]['commit']))
results = []
for tag, commit in selected:
    results.append(git_create_tag(tag, commit))
print(len(selected))

packages = ['rich','jinja2','pip','matplotlib','scipy','sqlalchemy','pytest','numpy','pydantic','idna','attrs','wheel','flask','httpx','urllib3','pandas']
results = {}
for p in packages:
    results[p] = pypi_package(p)['version']
majors = [int(v.split('.')[0]) for v in results.values()]
print(sum(majors))

tickets = db_list_tickets('open')
close_ids = []
for tid in tickets:
    t = db_get_ticket(tid)
    if t['age_days'] > 14:
        close_ids.append(tid)
for tid in close_ids:
    db_update_ticket(tid, 'closed')
print(len(close_ids))
